// Function to check if a number is even
pub fn is_even(n: u32) -> bool {
    n % 2 == 0
}

// Function to execute the is_even check
pub fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

// Function to determine if there is at least one even number in the array
pub fn is_product_even(arr: &Vec<u32>) -> bool {
    for &num in arr {
        if is_even(num) {
            return true;
        }
    }
    false
}

// Example usage
fn main() {
    let numbers = vec![1, 3, 5, 7];
    println!("Contains even number: {}", is_product_even(&numbers)); // false

    let numbers_with_even = vec![1, 2, 3, 4];
    println!("Contains even number: {}", is_product_even(&numbers_with_even)); // true
}